-- =====================================================================
-- Trainer-App FC Seuzach · Hallenplan bis Ostern 2027
-- 30 Hallentrainings (Mi 17.00–18.15, Sa 10.00–11.30), 21.10.2026–27.03.2027,
-- 6 Themen im Wechsel. Ohne Weihnachts- (19.12.–3.1.) und Sportferien (6.2.–21.2.)
-- und ohne Samstage mit Turnier (eingeteilt/angemeldet). Dazu 18 weitere Manual-Übungen.
-- Ersetzt alle künftigen Trainings, bei denen noch KEINE Anwesenheit erfasst ist.
-- =====================================================================

insert into exercises(id, team_id, place, phase, name, page, data) values
  ('ex37', null, 'hall', 'ein', 'Autorennen', '61', '{"src":"J+S-Manual Fussball Kinder","org":"Feld mit verteilten Toren aus Hütchen in verschiedenen Farben. Paare, jedes Kind mit Ball.","offen":"Zwei Kinder dribbeln mit je einem Ball durch die verteilten Tore auf die gegenüberliegende Seite und erfüllen Aufgaben, z. B. nur durch die roten Tore und den gleichen Weg zurück oder einander folgen.","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist; Hindernissen und anderen Kindern ausweichen, Finten schlagen (Übersteiger, Schere, schneller Richtungswechsel).","wett":"Team Rot und Weiss stehen einander gegenüber. Welches Team durchdribbelt die vorgegebene Route am schnellsten?","coach":["Den Ball als Hund bei Fuss halten (S. 42)"],"var":"Mehr oder engere Tore machen es schwerer.","videos":[{"title":"J+S-Video: Trainingsformen zur Einleitung","url":"http://jsle.ch/dVEi"}],"d":{"s":"hall","items":[["c",22,12],["c",22,20],["c",40,40],["c",40,48],["c",58,14],["c",58,22],["c",76,42],["c",76,50],["c",50,28],["c",50,36],["A",8,18,1],["A",8,46,1],["B",92,18,1],["B",92,46,1],["drib",10,18,48,32],["drib",10,46,38,44],["drib",90,18,60,18],["txt",50,62,"Durch die Tore dribbeln"]]}}'::jsonb),
  ('ex38', null, 'hall', 'ein', 'Reise zum Mond', '61', '{"src":"J+S-Manual Fussball Kinder","org":"Feld als «Universum» mit blauen Reifen (Planeten), gelben Markierungstellern (Monde) und kleinen Toren (Sterne). Jedes Kind mit Ball.","offen":"Die Kinder dribbeln durch das Universum und erfüllen Aufgaben, z. B. nur um die blauen Reifen bzw. die gelben Monde dribbeln oder einander folgen.","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist; einen Trick vorzeigen und nachahmen lassen.","wett":"Sternenschiessen: Wer schiesst in zwei Minuten am meisten Tore (Sterne)? Nach jedem Schuss Ball holen, zum Mond zurückführen, um einen Gegenstand dribbeln und ein neues Tor suchen.","coach":["Kopf hoch, Übersicht behalten"],"var":"Mehr Hindernisse oder kleinere Tore machen es schwerer.","videos":[{"title":"J+S-Video: Reise zum Mond","url":"http://jsle.ch/dErm"}],"d":{"s":"hall","items":[["hoop",24,18],["hoop",70,46],["hoop",50,30],["c",34,44],["c",62,16],["c",80,26],["m",8,32],["m",92,12,1],["m",92,52,1],["A",18,28,1],["A",40,12,1],["A",58,40,1],["A",76,34,1],["A",30,52,1],["drib",20,28,46,30],["drib",78,34,90,14],["shot",32,52,7,34],["txt",50,62,"Planeten, Monde und Sterne"]]}}'::jsonb),
  ('ex39', null, 'hall', 'ein', 'Trikottausch', '62', '{"src":"J+S-Manual Fussball Kinder","org":"Feld mit einem freien, markierten Feld in der Mitte. Alle Kinder dribbeln mit Ball und halten einen farbigen Überzieher in der Hand.","offen":"Auf dein Zeichen dribbeln die Kinder ins Mittelfeld und tauschen ihren Überzieher mit einem anderen Kind. Variation: nur eine Farbe schicken, oder vorgeben, wer mit wem tauscht (Rot zu Gelb, Gelb zu Blau …).","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist.","wett":"Welche Farbe durchdribbelt das Mittelfeld am schnellsten? Welches Farbteam findet sich am schnellsten in der Mitte zusammen?","coach":["Vor dem Tausch Kopf hoch und Partner suchen"],"var":"Kleineres Mittelfeld macht es enger.","videos":[{"title":"J+S-Video: Trikottausch","url":"http://jsle.ch/deTT"}],"d":{"s":"hall","items":[["area",8,6,84,52],["zone",38,22,24,20,"Tausch"],["A",16,14,1],["B",80,16,1],["N",20,48,1],["A",82,48,1],["B",30,30,1],["N",70,30,1],["drib",18,16,40,26],["drib",78,18,60,26],["drib",22,46,40,38]]}}'::jsonb),
  ('ex40', null, 'hall', 'ein', 'Finten-Star', '63', '{"src":"J+S-Manual Fussball Kinder","org":"Zwei Reihen stehen sich gegenüber, Abstand ca. 15 m. Für das Wetteifern Hütchentore links und rechts in der Mitte.","offen":"Auf dein Zeichen dribbeln zwei gegenüberstehende Kinder aufeinander zu, machen in der Mitte einen Richtungswechsel (180 Grad) und dribbeln zurück. Danach mit einer Finte in der Mitte auf die andere Seite.","ueben":"Richtung mit Sohle, Innen- oder Aussenrist wechseln; Finten als Körpertäuschung, Übersteiger oder Schere.","wett":"Weiss probiert, bei Rot im 1:1 durch die Hütchentore links oder rechts zu dribbeln. 2–3 Minuten, dann tauschen. Wer erzielt mehr Tore?","coach":["Täuschen und schlau sein wie ein Fuchs (S. 42)","Richtiges Timing: nicht zu früh, nicht zu spät"],"var":"Breitere Hütchentore erleichtern den Durchbruch.","videos":[{"title":"J+S-Video: Trainingsformen zur Einleitung","url":"http://jsle.ch/dVEi"}],"d":{"s":"hall","items":[["A",10,26,1],["A",10,32],["A",10,38],["B",90,26,1],["B",90,32],["B",90,38],["drib",13,26,44,28],["drib",87,26,56,28],["c",50,10],["c",50,18],["c",50,46],["c",50,54],["txt",50,32,"Finte"],["txt",50,62,"Hütchentore für das 1:1"]]}}'::jsonb),
  ('ex41', null, 'hall', 'ein', 'Im Regenbogenwald', '64', '{"src":"J+S-Manual Fussball Kinder","org":"Grosses Feld, darin mehrere kleinere Felder, je mit einer Farbe markiert. Jedes Kind mit Ball.","offen":"Alle dribbeln frei im Feld. Hebst du einen farbigen Markierkegel hoch, dribbeln die Kinder ins entsprechend markierte Feld.","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist.","wett":"Mehrere Teams: Welches ist am schnellsten im angezeigten Feld? Mehrere Farben nacheinander anzeigen, die durchdribbelt werden müssen, bevor die Teams zurückkehren.","coach":["Rundumblick: Kopf hoch beim Dribbeln (S. 42)"],"var":"Weiter auseinanderliegende Felder bedeuten längere Wege.","videos":[{"title":"J+S-Video: Trainingsformen zur Einleitung","url":"http://jsle.ch/dVEi"}],"d":{"s":"hall","items":[["area",4,4,92,56],["zone",8,8,18,14,"rot"],["zone",74,8,18,14,"blau"],["zone",8,42,18,14,"gelb"],["zone",74,42,18,14,"grün"],["A",40,22,1],["A",56,38,1],["B",46,44,1],["B",60,18,1],["drib",42,22,26,16],["drib",62,18,74,14],["drib",58,40,74,48]]}}'::jsonb),
  ('ex42', null, 'hall', 'sp', 'Wechseltore', '65', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld mit Mittellinie und je zwei Minitoren pro Hälfte (vier Tore). 3:3.","offen":"Dribbelt ein Kind über die Mittellinie, kann es in dieser Hälfte ein Tor erzielen. Dribbelt es wieder zurück, sind die anderen beiden Tore freigeschaltet. Bei Ballgewinn zuerst über die Mittellinie dribbeln.","ueben":"Täuschen und in den freien Raum dribbeln; als Mitspieler/in freilaufen, anspielbar sein und zupassen.","wett":"Welches Team erzielt in fünf Minuten mehr Tore? Welchem Team gelingt ein gutes Zusammenspiel?","coach":["Nach Ballgewinn sofort umschalten: Blume öffnen (S. 42)"],"var":"Breiteres Feld gibt mehr Raum.","videos":[{"title":"J+S-Video: Trainingsformen zum Dribbling","url":"http://jsle.ch/dDrB"}],"d":{"s":"hall","items":[["line",50],["m",0,14],["m",0,50],["m",100,14,1],["m",100,50,1],["A",30,20],["A",36,44,1],["A",58,30],["B",64,18],["B",70,42],["B",42,32],["drib",38,44,62,48],["shot",64,48,99,50],["txt",50,62,"Über die Mittellinie = Tore frei"]]}}'::jsonb),
  ('ex43', null, 'hall', 'sp', 'Spiel übers Kreuz', '66', '{"src":"J+S-Manual Fussball Kinder","org":"Quadratisches Feld mit vier Minitoren, je eines pro Seite (zwei blaue, zwei gelbe). 3:3.","offen":"Rot greift die blauen Tore an und verteidigt die gelben, Weiss umgekehrt. Variante: Nach einem Tor wechseln die zugeteilten Tore.","ueben":"Den Überblick behalten und das gegnerische Team mit schnellen Richtungswechseln überraschen.","wett":"Welches Team schliesst auf beide Tore erfolgreich ab?","coach":["Rundumblick: Wo ist das freie Tor?"],"var":"Tore näher zusammen oder weiter auseinander stellen.","videos":[{"title":"J+S-Video: Trainingsformen zum Dribbling","url":"http://jsle.ch/dDrB"}],"d":{"s":"hall","items":[["area",20,2,60,60],["m",50,4],["m",50,60],["m",22,32],["m",78,32,1],["txt",50,12,"blau"],["txt",50,54,"blau"],["txt",30,34,"gelb"],["txt",70,34,"gelb"],["A",40,26,1],["A",60,40],["A",34,46],["B",56,22],["B",46,38],["B",66,30],["drib",42,26,48,10],["shot",48,9,50,5]]}}'::jsonb),
  ('ex44', null, 'hall', 'sp', 'Tore in der Mitte', '71', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld, zwei Minitore Rücken an Rücken in der Feldmitte (ein Tor für jedes Team). 3:3.","offen":"Rot greift auf die beiden Tore von Weiss an und umgekehrt.","ueben":"Ganzes Feld nutzen und sich geschickt freilaufen; mit Zusammenspiel und Dribblings zum Abschluss.","wett":"Welches Team erzielt innerhalb von fünf Minuten mehr Tore?","coach":["Breite und Tiefe: Anspielstationen vorne, hinten, seitlich (S. 42)"],"var":"Grösseres Feld gibt mehr Raum für Spielverlagerungen.","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}],"d":{"s":"hall","items":[["area",4,4,92,56],["m",52,26,1],["m",48,38],["A",20,16],["A",26,46,1],["A",74,20],["B",76,46],["B",30,30],["B",64,34],["pass",28,46,72,22],["shot",72,24,54,26],["txt",50,62,"Tore in der Feldmitte"]]}}'::jsonb),
  ('ex45', null, 'hall', 'sp', 'Jokerspiel im Feld', '73', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld mit zwei Toren, 4:4 und zwei Joker (spielen immer mit dem Team in Ballbesitz).","offen":"Die Kinder spielen 4:4 mit zwei Jokern. Alle beteiligen sich am Angriffsspiel.","ueben":"Bei Ballbesitz Blume öffnen und mit Zusammenspiel Breite, Tiefe und Überzahl nutzen. Nach Ballverlust Blume schnell schliessen und im Schwarm den Ball jagen.","wett":"Welches Team erzielt innerhalb von fünf Minuten mehr Tore?","coach":["Bei Ballbesitz die Blume öffnen, bei Ballverlust schliessen (S. 42)"],"var":"Joker nur mit zwei Kontakten macht es schwerer.","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}],"d":{"s":"hall","items":[["G","L"],["G","R"],["A",20,14],["A",24,50],["A",40,32,1],["A",60,12],["B",64,44],["B",80,30],["B",56,28],["B",34,18],["N",48,50],["N",70,20],["pass",42,33,48,48],["pass",50,48,70,22],["shot",72,21,99,30]]}}'::jsonb),
  ('ex46', null, 'hall', 'le', 'Vom 1:0 zum 3:3', '70', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld mit zwei Toren, zwei Teams an den Seitenlinien, jedes Kind mit Ball.","offen":"Ein Kind von Weiss dribbelt ins Feld und erzielt so schnell wie möglich ein Tor. Dann kommt ein Kind von Rot dazu (1:1). Nach jedem Tor oder Aus kommt abwechselnd ein weiteres Kind mit neuem Ball dazu (2:1, 2:2 …), bis 3:3. Danach noch drei Bälle, dann beginnt Rot.","ueben":"In Überzahl mit schnellem Passspiel zum Torerfolg; in Gleichzahl freilaufen und mit Dribbling oder Pässen Tore erzielen.","wett":"Welches Team erzielt bis zum 3:3 mehr Tore?","coach":["Überzahl erkennen und schnell nutzen"],"var":"Grösseres Feld erleichtert das Zusammenspiel.","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}],"d":{"s":"hall","items":[["G","L"],["G","R"],["A",30,62],["A",36,62],["A",42,62],["B",58,2],["B",64,2],["B",70,2],["A",40,36,1],["B",62,26],["run",36,60,46,46],["drib",42,36,76,34],["shot",78,34,99,31],["txt",50,54,"1:0 → 1:1 → 2:1 → … → 3:3"]]}}'::jsonb),
  ('ex47', null, 'hall', 'le', '2:1', '70', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld mit zwei Toren und einer roten Linie als Grenze. Paare greifen gegen eine/n Verteidiger/in an.","offen":"Die Kinder spielen 2:1. Diverse Startpositionen vorgeben: seitlich, nebeneinander, vor dem verteidigenden Kind.","ueben":"Situationen schnell einschätzen, in die Sonne laufen (freilaufen) und Überzahl durch Zusammenspiel nutzen.","wett":"Zähl z. B. das linke Tor doppelt oder gib für einen erfolgreichen Pass oder ein Dribbling einen Extrapunkt.","coach":["Aus dem Schatten in die Sonne laufen (S. 42)","Vor dem Pass ein Foto vom Ziel machen"],"var":"Verteidiger startet näher oder weiter weg.","videos":[{"title":"J+S-Video: 2:1","url":"http://jsle.ch/d2v1"}],"d":{"s":"hall","items":[["m",100,18,1],["m",100,46,1],["line",40],["A",20,24,1],["A",20,42],["B",64,32],["drib",22,24,50,22],["run",22,42,66,46],["pass",52,23,64,44],["shot",66,46,99,47],["txt",40,62,"Grenze"]]}}'::jsonb),
  ('ex48', null, 'hall', 'le', 'Angreifen in Überzahl – 3:2', '72', '{"src":"J+S-Manual Fussball Kinder","org":"Feld mit Mittellinie und zwei Toren. Team Rot greift an, zwei Verteidiger/innen von Weiss: Kind 1 startet hinter den Toren, Kind 2 im Feld.","offen":"Team Rot greift auf die beiden Tore an. Ab der Mittellinie darf geschossen werden. Kind 1 (hinter den Toren) startet nach dem ersten Ballkontakt von Kind 2. Tor oder Aus beendet den Angriff.","ueben":"Durch schnelles und präzises Zusammenspiel oder Dribbling die Verteidigung ausspielen und sofort den Abschluss suchen.","wett":"Welchem Team gelingen trotz erhöhtem Verteidigerdruck ein präzises Zusammenspiel und ein rascher Torerfolg?","coach":["Breite des Feldes nutzen","Vor dem Tor entschlossen wie eine Raubkatze"],"var":"Leichter: 3:1 (S. 72). Schwerer: 3:3 (S. 72).","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}],"d":{"s":"hall","items":[["line",50],["m",100,18,1],["m",100,46,1],["A",30,12],["A",30,32,1],["A",30,52],["B",62,30],["B",98,4],["run",96,6,76,22],["pass",32,31,46,14],["run",30,52,70,50],["drib",46,14,66,16],["pass",68,17,72,48],["shot",74,48,99,46]]}}'::jsonb),
  ('ex49', null, 'hall', 'le', 'Jokerspiel seitlich', '73', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld mit zwei Toren, Aussenbahnen markiert. 2:2 im Feld, je zwei Joker auf den Aussenbahnen.","offen":"Die Kinder spielen 2:2 mit zwei Jokern auf den Aussenbahnen. Die Joker dürfen den Ball max. zweimal berühren.","ueben":"Joker miteinbeziehen und so Breite und Überzahl nutzen.","wett":"Welches Team erzielt unter Einbezug der Joker ein Tor?","coach":["Breit spielen, dann schnell in die Mitte"],"var":"Joker nur mit einem Kontakt macht es schwerer.","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}],"d":{"s":"hall","items":[["zone",0,0,100,9,"Aussenbahn"],["zone",0,55,100,9,"Aussenbahn"],["G","L"],["G","R"],["N",40,4],["N",62,60],["A",30,26,1],["A",52,42],["B",60,24],["B",70,40],["pass",32,25,40,7],["pass",42,6,72,30],["shot",74,31,99,31]]}}'::jsonb),
  ('ex50', null, 'hall', 'le', 'Jokerspiel vertikal', '73', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld mit zwei Toren. 3:3, zwei Joker im Feld und zwei Joker ausserhalb hinter den Grundlinien.","offen":"Die Kinder spielen 3:3 mit zwei Jokern im Feld und zwei Jokern ausserhalb (zwei Ballkontakte). Alle beteiligen sich am Angriffsspiel.","ueben":"Aussenspieler/innen und Joker im Feld einbeziehen und so Tiefe und Überzahl nutzen.","wett":"Tore mit Einbezug der Joker in der Tiefe zählen doppelt.","coach":["Pass in die Tiefe: Foto vom Ziel machen"],"var":"Joker in der Tiefe direkt spielen lassen macht es schwerer.","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}],"d":{"s":"hall","items":[["m",100,14,1],["m",100,50,1],["m",0,14],["m",0,50],["N",96,32],["N",4,32],["N",50,20],["N",52,46],["A",26,18],["A",34,44,1],["A",62,30],["B",70,16],["B",74,46],["B",42,30],["pass",36,43,50,22],["pass",52,21,94,31],["pass",94,34,66,46],["shot",68,47,99,50]]}}'::jsonb),
  ('ex51', null, 'hall', 'le', 'Tigerball – am Tiger vorbei', '74', '{"src":"J+S-Manual Fussball Kinder","org":"Mehrere kleine Felder. Zwei Kinder passen sich den Ball flach zu, ein Kind in der Mitte ist der Tiger.","offen":"Die beiden passen sich den Ball flach zu und sind immer anspielbar. Schaffen sie drei Pässe, ohne dass der Tiger den Pass unterbindet? Erobert der Tiger den Ball, tauscht er mit dem Kind, das gepasst hat. Vereinfachen: Pylonen als Tiger.","ueben":"Geschickt im Rücken des Tigers freilaufen, aus dem Schatten in die Sonne.","wett":"Wie viele Pässe gelingen am Tiger vorbei?","coach":["Fuss als Golfschläger: fest anspannen und ausdrehen (S. 70)","Vor dem Pass ein Foto machen"],"var":"Grösseres Feld erleichtert die Pässe.","videos":[{"title":"J+S-Video: Trainingsformen zu Passen und Ballkontrolle","url":"http://jsle.ch/dPaB"}],"d":{"s":"hall","items":[["area",6,10,40,44],["A",12,20,1],["A",38,44],["B",26,32],["pass",14,21,37,42],["run",38,44,40,34],["area",54,10,40,44],["A",60,44],["A",86,18,1],["B",74,30],["pass",85,20,62,42],["txt",50,62,"Aus dem Schatten in die Sonne"]]}}'::jsonb),
  ('ex52', null, 'hall', 'le', 'Torschussduell mit Seitenhilfe', '78', '{"src":"J+S-Manual Fussball Kinder","org":"Kleinfeld mit zwei Toren und Torspieler/innen. 2:2 im Feld, Joker an den Seitenlinien.","offen":"Die Kinder versuchen im 2:2, mithilfe der Kinder ausserhalb des Feldes (Joker) ein Tor zu erzielen.","ueben":"Mithilfe der Aussen- und Torspieler/innen Breite und Überzahl nutzen und entschlossen abschliessen.","wett":"Welches Team nutzt die Überzahl in Ballbesitz am erfolgreichsten?","coach":["Vor dem Tor entschlossen wie eine Raubkatze (S. 75)","Torspieler/in: wie eine Katze springen und Bälle krallen"],"var":"Joker nur mit einem Kontakt macht es schwerer.","videos":[{"title":"J+S-Video: Trainingsformen zum Torabschluss","url":"http://jsle.ch/dTor"}],"d":{"s":"hall","items":[["G","L"],["G","R"],["B",3,32],["A",97,32],["N",30,0],["N",66,64],["A",36,30,1],["A",46,46],["B",60,26],["B",62,40],["pass",38,29,31,3],["pass",33,2,70,20],["shot",72,21,96,30]]}}'::jsonb),
  ('ex53', null, 'hall', 'le', '1:1 Torabschluss frontal', '79', '{"src":"J+S-Manual Fussball Kinder","org":"Feld mit zwei Toren, zwei Teams an den Grundlinien. Auf beiden Seiten startet gleichzeitig ein Duell.","offen":"Ein Kind aus Rot passt zu einem Kind aus Weiss. Danach starten beide zum 1:1 und versuchen, beim Gegenüber ein Tor zu erzielen. Auf der anderen Seite startet gleichzeitig ein Duell, dort passt Weiss zu Rot.","ueben":"Mit Tempo und Täuschungen das verteidigende Kind ausdribbeln und entschlossen abschliessen.","wett":"Welches Team erzielt am meisten Tore?","coach":["Mutig ins 1:1, Tempo und Rhythmuswechsel","Vor dem Schuss ein Foto vom Tor machen"],"var":"Schmaleres Feld macht das 1:1 schwerer.","videos":[{"title":"J+S-Video: Trainingsformen zum Torabschluss","url":"http://jsle.ch/dTor"}],"d":{"s":"hall","items":[["line",50],["m",0,16],["m",100,16,1],["m",0,48],["m",100,48,1],["A",8,8],["A",8,14],["B",92,8],["B",92,14],["pass",10,10,88,16],["B",70,20,1],["A",30,18],["drib",68,21,40,22],["shot",36,21,1,17],["A",8,52],["B",92,52],["txt",50,60,"gleichzeitig zweites Duell"]]}}'::jsonb),
  ('ex54', null, 'hall', 'le', 'Grosser Torschussrundlauf', '75', '{"src":"J+S-Manual Fussball Kinder","org":"Markiertes Viereck in der Mitte, rundherum acht Minitore. Jedes Kind mit Ball.","offen":"Alle starten gleichzeitig: aus dem Viereck herausdribbeln und mit der nächsten Ballberührung in eines der acht Tore abschliessen (freie Wahl). Ball holen, zurück ins Viereck und auf das nächste freie Tor schiessen.","ueben":"Vor dem Schiessen ein Foto vom Tor machen und in die freie Ecke zielen.","wett":"Wie viele Tore erzielen die Kinder mit dem linken und wie viele mit dem rechten Fuss?","coach":["Präzision vor Kraft (S. 42)","Beidfüssig üben"],"var":"Grösserer Abstand zu den Toren macht es schwerer.","videos":[{"title":"J+S-Video: Grosser Torschussrundlauf","url":"http://jsle.ch/dGTR"},{"title":"J+S-Video: Trainingsformen zum Torabschluss","url":"http://jsle.ch/dTor"}],"d":{"s":"hall","items":[["zone",36,20,28,24,"Viereck"],["m",4,14],["m",4,50],["m",96,14,1],["m",96,50,1],["m",30,4],["m",70,4],["m",30,60],["m",70,60],["A",44,26,1],["A",56,38,1],["A",40,40,1],["A",60,24,1],["drib",46,26,30,16],["shot",28,15,6,14],["drib",58,39,70,48],["shot",70,49,70,58]]}}'::jsonb)
on conflict (id) do update set data = excluded.data, name = excluded.name, page = excluded.page, phase = excluded.phase;

delete from trainings t
 where t.team_id = 'e-junioren' and t.date >= current_date
   and not exists (select 1 from attendance a where a.training_id = t.id);

